export type ParsedRefundInstruction<
  TProgram extends string = typeof PREDICTION_MIGRATOR_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    market: TAccountMetas[0];
    entry: TAccountMetas[1];
    marketAuthority: TAccountMetas[2];
    potVault: TAccountMetas[3];
    baseMint: TAccountMetas[4];
    quoteMint: TAccountMetas[5];
    refunderBaseAta: TAccountMetas[6];
    refunderQuoteAta: TAccountMetas[7];
    refunder: TAccountMetas[8];
    baseTokenProgram: TAccountMetas[9];
    quoteTokenProgram: TAccountMetas[10];
  };
  data: RefundInstructionData;
};

export function parseRefundInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRefundInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 11) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 11,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      market: getNextAccount(),
      entry: getNextAccount(),
      marketAuthority: getNextAccount(),
      potVault: getNextAccount(),
      baseMint: getNextAccount(),
      quoteMint: getNextAccount(),
      refunderBaseAta: getNextAccount(),
      refunderQuoteAta: getNextAccount(),
      refunder: getNextAccount(),
      baseTokenProgram: getNextAccount(),
      quoteTokenProgram: getNextAccount(),
    },
    data: getRefundInstructionDataDecoder().decode(instruction.data),
  };
}
